public static class CsvBatch
{
    public static IReadOnlyList<string> Split(string row, char delimiter = ',') =>
        row.Split(delimiter);

    public static void Emit(params IEnumerable<string> cells)
    {
        foreach (var cell in cells)
        {
            Console.WriteLine(cell);
        }
    }
}

CsvBatch.Emit("attemptId", "userId", "score");
CsvBatch.Emit(["attemptId", "userId", "score"]);
